  function 成长技能模板项_唐三(魂技名, 写入类型, 写入路径, 触发事件标识, 原著发生时间, 触发关键词, 需求魂环数, 画面描述, 效果描述, 额外 = {}) {
    const 技能数据补录 = 唐三效果补录[`${写入类型}|${写入路径}|${魂技名}`] || {};
    return Object.freeze({ 魂技名, 写入类型, 写入路径, 触发事件标识, 原著发生时间, 触发关键词: Object.freeze(触发关键词), 需求魂环数, ...额外, 技能数据: Object.freeze({ 魂技名, 画面描述, 效果描述, ...技能数据补录 }) });
  }

  function 角色成长技能模板项(所属角色, 模板列表) {
    return Object.freeze(模板列表.map(模板 => Object.freeze({ 所属角色, ...模板 })));
  }

